17,sonic-utilities,dump/plugins/vlan.py,5e95fc349665b7e9ecc32f86e5a5e0ba32e2bd86,5e95fc349665b7e9ecc32f86e5a5e0ba32e2bd86,# Convert 'Vlanxxx' to 'xxx',accepted,True,,1,1,ACCEPT,NO,False,pass,context_required,context_required,True,1.0,forced_route:context_required,,0,0.08863282453832207,0.062236884187601364,0.22222222222222224,pass,True,0.6,0.6,context_required,medium,snippet,0.7,0.7,0.3,0.6,0.6,0.6,0.6,0.7,context_router_no_context | bypass_analysis_legacy,,,fixer_only_analyzer_skipped,Pass directly to fixer for snippet-only developer-like repair.,partial,partial,partial,partial,# Convert 'Vlanxxx' to 'xxx',snippet-only route,False,none,,method_context,method,0,0,0,0,0,0,MatchRequest,MatchRequest,,1,"[{""method_name"": ""MatchRequest"", ""path"": ""dump/match_infra.py"", ""class_name"": null, ""start_line"": 27, ""end_line"": 126, ""source"": ""class MatchRequest:
    """"""
    Request Object which should be passed to the MatchEngine

    Attributes:
    ""table""             : A Valid Table Name
    ""key_pattern""       : Pattern of the redis-key to match. Defaults to ""*"". Eg: ""*"" will match all the keys.
                          Supports these glob style patterns. https://redis.io/commands/KEYS
    ""field""             : Field to check for a match,Defaults to None
    ""value""             : Value to match, Defaults to None
    ""return_fields""     : An iterable type, where each element woudld imply a field to return from all the filtered keys
    ""db""                : A Valid DB name, Defaults to """".
    ""file""              : A Valid Config JSON file, Eg: copp_cfg.json, Defaults to """".
                          Only one of the db/file fields should have a non-empty string.
    ""just_keys""         : If true, Only Returns the keys matched. Does not return field-value pairs. Defaults to True
    ""ns""                : namespace argument, if nothing is provided, default namespace is used
    ""match_entire_list"" : When this arg is set to true, entire list is matched incluing the "","".
                          When False, the values are split based on "","" and individual items are matched with
    """"""

    def __init__(self, **kwargs):
        self.table = kwargs[""table""] if ""table"" in kwargs else None
        self.key_pattern = kwargs[""key_pattern""] if ""key_pattern"" in kwargs else ""*""
        self.field = kwargs[""field""] if ""field"" in kwargs else None
        self.value = kwargs[""value""] if ""value"" in kwargs else None
        self.return_fields = kwargs[""return_fields""] if ""return_fields"" in kwargs else []
        self.db = kwargs[""db""] if ""db"" in kwargs else """"
        self.file = kwargs[""file""] if ""file"" in kwargs else """"
        self.just_keys = kwargs[""just_keys""] if ""just_keys"" in kwargs else True
        self.ns = kwargs[""ns""] if ""ns"" in kwargs else """"
        self.match_entire_list = kwargs[""match_entire_list""] if ""match_entire_list"" in kwargs else False
        err = self.__static_checks()
        verbose_print(str(err))
        if err:
            raise Exception(""Static Checks for the MatchRequest Failed, Reason: \n"" + err)

    def __static_checks(self):

        if not self.db and not self.file:
            return EXCEP_DICT[""NO_SRC""]

        if self.db and self.file:
            return EXCEP_DICT[""SRC_VAGUE""]

        if not self.db:
            try:
                with open(self.file) as f:
                    json.load(f)
            except Exception as e:
                return EXCEP_DICT[""FILE_R_EXEP""] + str(e)

        if not self.file and self.db not in SonicDBConfig.getDbList():
            return EXCEP_DICT[""INV_DB""]

        if not self.table:
            return EXCEP_DICT[""NO_TABLE""]

        if not isinstance(self.return_fields, list):
            return EXCEP_DICT[""BAD_FORMAT_RE_FIELDS""]

        if not self.just_keys and self.return_fields:
            return EXCEP_DICT[""JUST_KEYS_COMPAT""]

        if self.field and not self.value:
            return EXCEP_DICT[""NO_VALUE""]

        if self.ns != DEFAULT_NAMESPACE and self.ns not in multi_asic.get_namespace_list():
            return EXCEP_DICT[""INV_NS""] + "" Choose From {}"".format(multi_asic.get_namespace_list())

        verbose_print(""MatchRequest Checks Passed"")

        return """"

    def __str__(self):
        str = ""----------------------- \n MatchRequest: \n""
        if self.db:
            str += ""db:{} , "".format(self.db)
        if self.file:
            str += ""file:{} , "".format(self.file)
        if self.table:
            str += ""table:{} , "".format(self.table)
        if self.key_pattern:
            str += ""key_pattern:{} , "".format(self.key_pattern)
        if self.field:
            str += ""field:{} , "".format(self.field)
        if self.value:
            str += ""value:{} , "".format(self.value)
        if self.just_keys:
            str += ""just_keys:True ,""
        else:
            str += ""just_keys:False ,""
        if len(self.return_fields) > 0:
            str += ""return_fields: "" + "","".join(self.return_fields) + "" ""
        if self.ns:
            str += ""namespace: , "" + self.ns
        if self.match_entire_list:
            str += ""match_list: True , ""
        else:
            str += ""match_list: False , ""
        return str"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",{},[],[],True,skipped_fixer_only,"def init_asic_vlan_info(self, vlan_name):

18,unfurl,unfurl/init.py,a1ad116e9ce81452ce2f173abba2561d88afcf18,a1ad116e9ce81452ce2f173abba2561d88afcf18,# XXX if sourcePath points to an explicit file we should check if it's a service template first,accepted,True,,1,1,ACCEPT,NO,False,pass,context_required,context_required,True,1.0,forced_route:context_required,,0,0.0,0.0,0.0,pass,True,0.6,0.6,context_required,medium,snippet,0.7,0.7,0.3,0.6,0.6,0.6,0.6,0.7,context_router_no_context | bypass_analysis_legacy,,,fixer_only_analyzer_skipped,Pass directly to fixer for snippet-only developer-like repair.,partial,partial,partial,partial,# XXX if sourcePath points to an explicit file we should check if it's a service template first,snippet-only route,False,none,,method_context,method,0,0,0,0,0,0,_looksLike | LocalEnv,_looksLike | LocalEnv,,2,"[{""method_name"": ""_looksLike"", ""path"": ""unfurl/init.py"", ""class_name"": null, ""start_line"": 310, ""end_line"": 316, ""source"": ""def _looksLike(path, name):
    # in case path is a directory:
    if os.path.isfile(os.path.join(path, name)):
        return path, name
    if path.endswith(name):  # name is explicit so don't need to check if file exists
        return os.path.split(path)
    return None"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""LocalEnv"", ""path"": ""unfurl/localenv.py"", ""class_name"": null, ""start_line"": 304, ""end_line"": 585, ""source"": ""class LocalEnv(object):
    """"""
  This class represents the local environment that an ensemble runs in, including
  the local project it is part of and the home project.
  """"""

    homeProject = None

    def __init__(self, manifestPath=None, homePath=None, parent=None, project=None):
        """"""
    If manifestPath is None find the first unfurl.yaml or ensemble.yaml
    starting from the current directory.

    If homepath is set it overrides UNFURL_HOME
    (and an empty string disable the home path).
    Otherwise the home path will be set to UNFURL_HOME or the default home location.
    """"""
        import logging

        logger = logging.getLogger(""unfurl"")
        self.logger = logger

        if parent:
            self._projects = parent._projects
            self._manifests = parent._manifests
            self.homeConfigPath = parent.homeConfigPath
        else:
            self._projects = {}
            if project:
                self._projects[project.localConfig.config.path] = project
            self._manifests = {}
            self.homeConfigPath = getHomeConfigPath(homePath)
            if self.homeConfigPath and not os.path.exists(self.homeConfigPath):
                logger.warning(
                    'UNFURL_HOME is set but does not exist: ""%s""', self.homeConfigPath
                )

        if self.homeConfigPath:
            self.homeProject = self.getProject(self.homeConfigPath, None)

        self.manifestPath = None
        if manifestPath:
            # if manifestPath does not exist check project config
            if not os.path.exists(manifestPath):
                # XXX check if the manifest is named in the project config
                # pathORproject = self.findProject(os.path.dirname(manifestPath))
                # if pathORproject:
                #    self.manifestPath = pathORproject.getInstance(manifestPath)
                # else:
                raise UnfurlError(
                    ""Ensemble manifest does not exist: '%s'""
                    % os.path.abspath(manifestPath)
                )
            else:
                pathORproject = self.findManifestPath(manifestPath)
        else:
            # not specified: search current directory and parents for either a manifest or a project
            pathORproject = self.searchForManifestOrProject(""."")

        if isinstance(pathORproject, Project):
            self.project = pathORproject
            if not self.manifestPath:
                self.manifestPath = pathORproject.findDefaultInstanceManifest()
        else:
            self.manifestPath = pathORproject
            if project:
                self.project = project
            else:
                self.project = self.findProject(os.path.dirname(pathORproject))

        self.instanceRepo = self._getInstanceRepo()
        self.config = (
            self.project
            and self.project.localConfig
            or self.homeProject
            and self.homeProject.localConfig
            or LocalConfig()
        )

    def getVaultPassword(self, vaultId=""default""):
        secret = os.getenv(""UNFURL_VAULT_%s_PASSWORD"" % vaultId.upper())
        if not secret:
            context = self.getContext()
            secret = (
                context.get(""secrets"", {})
                .get(""attributes"", {})
                .get(""vault_%s_password"" % vaultId)
            )
        return secret

    def getManifest(self, path=None):
        from .yamlmanifest import YamlManifest

        if path and path != self.manifestPath:
            localEnv = LocalEnv(path, self.homeConfigPath, self)
            return localEnv.getManifest()
        else:
            manifest = self._manifests.get(self.manifestPath)
            if not manifest:
                vaultId = ""default""
                vault = makeVaultLib(self.getVaultPassword(vaultId), vaultId)
                if vault:
                    self.logger.info(
                        ""Vault password found, configuring vault id: %s"", vaultId
                    )
                manifest = YamlManifest(localEnv=self, vault=vault)
                self._manifests[self.manifestPath] = manifest
            return manifest

    def getProject(self, path, homeProject):
        path = Project.normalizePath(path)
        project = self._projects.get(path)
        if not project:
            project = Project(path, homeProject)
            self._projects[path] = project
        return project

    # manifestPath specified
    #  doesn't exist: error
    #  is a directory: either instance repo or a project
    def findManifestPath(self, manifestPath):
        if not os.path.exists(manifestPath):
            raise UnfurlError(
                ""Manifest file does not exist: '%s'"" % os.path.abspath(manifestPath)
            )

        if os.path.isdir(manifestPath):
            test = os.path.join(manifestPath, DefaultNames.Ensemble)
            if os.path.exists(test):
                return test
            else:
                test = os.path.join(manifestPath, DefaultNames.LocalConfig)
                if os.path.exists(test):
                    return self.getProject(test, self.homeProject)
                else:
                    message = (
                        ""Can't find an Unfurl ensemble or project in folder '%s'""
                        % manifestPath
                    )
                    raise UnfurlError(message)
        else:
            return manifestPath

    def _getInstanceRepo(self):
        instanceDir = os.path.dirname(self.manifestPath)
        if self.project and instanceDir in self.project.workingDirs:
            return self.project.workingDirs[instanceDir][1]
        else:
            return Repo.findContainingRepo(instanceDir)

    def getRepos(self):
        if self.project:
            repos = self.project.getRepos()
        else:
            repos = []
        if self.instanceRepo and self.instanceRepo not in repos:
            return repos + [self.instanceRepo]
        else:
            return repos

    def searchForManifestOrProject(self, dir):
        current = os.path.abspath(dir)
        while current and current != os.sep:
            test = os.path.join(current, DefaultNames.Ensemble)
            if os.path.exists(test):
                return test

            test = os.path.join(current, DefaultNames.LocalConfig)
            if os.path.exists(test):
                return self.getProject(test, self.homeProject)

            current = os.path.dirname(current)

        message = ""Can't find an Unfurl ensemble or project in the current directory (or any of the parent directories)""
        raise UnfurlError(message)

    def findProject(self, testPath):
        """"""
    Walk parents looking for unfurl.yaml
    """"""
        path = Project.findPath(testPath)
        if path is not None:
            return self.getProject(path, self.homeProject)
        return None

    def getContext(self, context=None):
        """"""
        Return a new context that merges the given context with the local context.
        """"""
        return self.config.getContext(self.manifestPath, context or {})

    def getEngine(self):
        context = self.getContext()
        runtime = context.get(""runtime"")
        if runtime:
            return runtime
        if self.project and self.project.venv:
            return ""venv:"" + self.project.venv
        if self.homeProject and self.homeProject.venv:
            return ""venv:"" + self.homeProject.venv
        return None

    def getLocalInstance(self, name, context):
        assert name in [""locals"", ""secrets"", ""local"", ""secret""]
        local = context.get(name, {})
        return (
            self.config.createLocalInstance(
                name.rstrip(""s""), local.get(""attributes"", {})
            ),
            local,
        )

    def findGitRepo(self, repoURL, isFile=True, revision=None):
        repo = None
        if self.project:
            repo = self.project.findGitRepo(repoURL, revision)
        if not repo:
            if self.homeProject:
                return self.homeProject.findGitRepo(repoURL, revision)
        return repo

    def findOrCreateWorkingDir(
        self, repoURL, isFile=True, revision=None, basepath=None
    ):
        repo = self.findGitRepo(repoURL, revision)
        # git-local repos must already exist
        if not repo and not repoURL.startswith(""git-local://""):
            if self.project and (
                basepath is None or self.project.isPathInProject(basepath)
            ):
                project = self.project
            else:
                project = self.homeProject
            if project:
                repo = project.createWorkingDir(repoURL, revision)
        if not repo:
            return None, None, None
        return (repo, repo.revision, revision and repo.revision != revision)

